<script setup>
import DirectoryEditor from './RenameDirectoryEditor.vue'
import {ArrowRight,Check,Folder,PenLine} from '@lucide/vue'
const props=defineProps({rows:Array,chosen:Set,busy:Boolean,results:Boolean,allChosen:Boolean,partlyChosen:Boolean,editingPath:String,directoryName:String,newDirectoryPath:String,directoryError:String,directoryBusy:Boolean,canRenameDirectory:Boolean})
const emit=defineEmits(['toggle','all','rename-directory','update:directoryName','save-directory','cancel-directory'])
const parent=row=>row.path.slice(0,row.path.lastIndexOf('/'))
const labels={ready:'待修改',unmatched:'未匹配',unchanged:'相同',invalid:'无效',conflict:'重名',done:'已完成',failed:'失败',pending:'未执行'}
</script>
<template>
 <div class="rename-table-scroll"><table class="rename-table"><colgroup><col style="width:38px"><col><col style="width:28px"><col><col style="width:80px"></colgroup><thead><tr><th><input type="checkbox" aria-label="全选可修改文件" :checked="allChosen" :indeterminate="partlyChosen" :disabled="busy||results" @change="emit('all',$event.target.checked)"></th><th>原文件名</th><th/><th>新文件名</th><th>状态</th></tr></thead><tbody><template v-for="(row,index) in rows" :key="row.index"><tr v-if="index===0||parent(row)!==parent(rows[index-1])" class="rename-folder-row"><td colspan="5"><div class="rename-folder-heading"><Folder :size="14"/><span>{{ parent(row) }}</span><button :disabled="directoryBusy" :aria-label="`修改目录名 ${parent(row)}`" @click="emit('rename-directory',parent(row))"><PenLine :size="14"/>修改目录名</button></div><DirectoryEditor v-if="editingPath===parent(row)" :name="directoryName" :path="editingPath" :new-path="newDirectoryPath" :error="directoryError" :busy="directoryBusy" :can-save="canRenameDirectory" @update:name="emit('update:directoryName',$event)" @save="emit('save-directory')" @cancel="emit('cancel-directory')"/></td></tr><tr :class="[`rename-state-${row.status}`,{'rename-chosen':chosen.has(row.index)}]"><td><Check v-if="row.status==='done'" :size="16"/><input v-else type="checkbox" :checked="chosen.has(row.index)" :disabled="busy||results||row.status!=='ready'" :aria-label="`选择 ${row.name}`" @change="emit('toggle',row.index)"></td><td :title="row.name">{{ row.name }}</td><td><ArrowRight :size="14"/></td><td :title="row.target">{{ row.target||'—' }}<small v-if="['invalid','conflict','failed'].includes(row.status)">{{ row.message }}</small></td><td>{{ labels[row.status] }}</td></tr></template></tbody></table><div v-if="!rows.length" class="rename-empty">暂无符合条件的文件</div></div>
</template>
